    site_id, source_type, source_id, target_type, target_id, medium_type,
    port_count, source_port, target_port, status, create_by, create_time, remark
) values (
    #{siteId}, #{sourceType}, #{sourceId}, #{targetType}, #{targetId}, #{mediumType},
    #{portCount}, #{sourcePort}, #{targetPort}, #{status}, #{createBy}, #{createTime}, #{remark}
