mapper.select:
select count(1) from sup_equipment_link
where site_id = #{siteId}
  and source_type = #{sourceType}
  and source_id = #{sourceId}
  and target_type = #{targetType}
  and target_id = #{targetId}
  and medium_type = #{mediumType}
  and ifnull(source_port, '') = ifnull(#{sourcePort}, '')
  and ifnull(target_port, '') = ifnull(#{targetPort}, '')

  and link_id <> #{linkId}
